targets.expr:
# CPU util
100 *
(
  sum(
    rate(container_cpu_usage_seconds_total{
        namespace="$namespace",
        metrics_path="/metrics/cadvisor",
        container!="",
        container!="POD",
    }[1m])
    * on (pod) group_left()
    kube_pod_labels{label_app="$application"}
  )
  /
  sum(
    kube_pod_container_resource_requests{
        namespace="$namespace",
        resource="cpu",
        unit="core",
    }
    * on (pod) group_left()
    kube_pod_labels{label_app="$application"}
  )
)

# Memory util
100 *
(
  sum(
    container_memory_working_set_bytes{
        namespace="$namespace",
        metrics_path="/metrics/cadvisor",
        container!="",
        container!="POD",
    }
    * on (pod) group_left()
    kube_pod_labels{label_app="$application"}
  )
  /
  sum(
    kube_pod_container_resource_requests{
        namespace="$namespace",
        resource="memory",
        unit="byte",
    }
    * on (pod) group_left()
    kube_pod_labels{label_app="$application"}
  )
)

sum(
  rate(container_cpu_usage_seconds_total{
    metrics_path="/metrics/cadvisor",
    container!=""
  }[1m])
  * on (pod) group_left
  kube_pod_labels{label_app="$application"}
)

sum(
  kube_pod_container_resource_requests{
    resource="cpu",
    unit="core"
  }
  * on (namespace,pod) group_left
  kube_pod_labels{label_app="$application"}
)

sum(
  container_memory_working_set_bytes{
    metrics_path="/metrics/cadvisor",
    container!=""
  }
  * on(pod) group_left
  kube_pod_labels{label_app="$application"}
) / 1024 / 1024

sum(
  kube_pod_container_resource_requests{
    resource="memory",
    unit="byte"
  }
  * on(namespace,pod) group_left
  kube_pod_labels{label_app="$application"}
) / 1024 / 1024

1000 * sum by (pod) (
  rate(container_cpu_usage_seconds_total{
    metrics_path="/metrics/cadvisor",
    container!=""
  }[1m])
  * on (pod) group_left
  kube_pod_labels{label_app="$application"}
)

sum by (pod) (
  container_memory_working_set_bytes{
    metrics_path="/metrics/cadvisor",
    container!=""
  }
  * on (pod) group_left
  kube_pod_labels{label_app="$application"}
) / 1024 / 1024
